  void AnimateCompactPower(FrameworkElement target,bool stopping){if(target==null||diagnostic||session==null||!session.State.CompactAnimations||!SystemParameters.ClientAreaAnimation)return;var p=CompactAnimationParameters(stopping);var scale=new ScaleTransform(1,1);var rotate=new RotateTransform(0);var translate=new TranslateTransform(0,0);var transforms=new TransformGroup();transforms.Children.Add(scale);transforms.Children.Add(rotate);transforms.Children.Add(translate);target.RenderTransformOrigin=new Point(.5,.5);target.RenderTransform=transforms;var duration=TimeSpan.FromMilliseconds(p[5]);scale.BeginAnimation(ScaleTransform.ScaleXProperty,new DoubleAnimation(1,p[0],duration){AutoReverse=true,EasingFunction=new QuadraticEase{EasingMode=EasingMode.EaseInOut}});scale.BeginAnimation(ScaleTransform.ScaleYProperty,new DoubleAnimation(1,p[1],duration){AutoReverse=true,EasingFunction=new QuadraticEase{EasingMode=EasingMode.EaseInOut}});if(p[2]!=0)rotate.BeginAnimation(RotateTransform.AngleProperty,new DoubleAnimation(0,p[2],duration){AutoReverse=true});if(p[3]!=0)translate.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(0,p[3],duration){AutoReverse=true});target.BeginAnimation(OpacityProperty,new DoubleAnimation(1,p[4],duration){AutoReverse=true});}
