  void ApplyCompactControlPalette(DependencyObject root){if(root==null)return;foreach(var slider in CompactLogicalChildren<Slider>(root).Concat(VisualChildren<Slider>(root)).Distinct()){if(slider.Style==null)slider.Style=(Style)FindResource("VkStreamBar");if(slider.Style==(Style)FindResource("VkStreamBar")){slider.Foreground=Brush(CompactVisualAccent);slider.Background=Brush(CompactLight?"#BBC6CE":"#34434E");}}foreach(var table in CompactLogicalChildren<DataGrid>(root).Concat(VisualChildren<DataGrid>(root)).Distinct())ApplyCompactGridPalette(table);var texts=CompactLogicalChildren<TextBlock>(root).Concat(VisualChildren<TextBlock>(root)).Distinct();foreach(var text in texts){var owner=VisualAncestor<Button>(text);if(owner!=null&&!Object.ReferenceEquals(owner.Content,text)){text.Foreground=owner.Foreground;continue;}if(CompactLight)text.Foreground=Brush(text.FontSize<=12?CompactSecondary:CompactPrimary);else if(text.ReadLocalValue(TextBlock.ForegroundProperty)==DependencyProperty.UnsetValue)text.Foreground=Brush(CompactPrimary);}foreach(var input in CompactLogicalChildren<Control>(root).Concat(VisualChildren<Control>(root)).Distinct().Where(item=>item is TextBox||item is ComboBox||item is PasswordBox)){input.Foreground=input.Name=="strategyArgumentValue"&&!input.IsKeyboardFocusWithin?Brushes.Transparent:Brush(CompactPrimary);input.Background=Brush(CompactLight?"#FFFFFFFF":"#FF20262D");input.BorderBrush=Brush(CompactOutline);if(input is ComboBox)ApplyCompactPickerPalette((ComboBox)input);}foreach(var list in CompactLogicalChildren<ListBox>(root).Concat(VisualChildren<ListBox>(root)).Distinct()){list.Foreground=Brush(CompactPrimary);if(list.Name=="wpfParameterName")list.Background=Brush(CompactSurface);}foreach(var check in CompactLogicalChildren<CheckBox>(root).Concat(VisualChildren<CheckBox>(root)).Distinct())check.Foreground=Brush(check.Name=="compactAutoPoolMark"?CompactVisualAccent:CompactPrimary);}
