    var panel=new StackPanel{Margin=new Thickness(0,8,0,8)};panel.Children.Add(Text("Автоопределение БС",18));var enabled=new CheckBox{Name="autoDetectBs",Content="Автоматически переключать VPN и БС",IsChecked=session.State.AutoDetectBs,Margin=new Thickness(0,8,0,6)};var intervals=CompactCadenceValues(session.State.AutoBsIntervalSeconds,15);var interval=new ComboBox{Name="autoBsInterval",ItemsSource=intervals.Select(CompactCadenceLabel).ToArray(),SelectedIndex=Math.Max(0,Array.IndexOf(intervals,session.State.AutoBsIntervalSeconds))};panel.Children.Add(enabled);panel.Children.Add(Field("Интервал",interval));var probe=AsyncButton("Проверить сеть сейчас",async()=>{if(!session.State.AutoDetectBs)throw new InvalidOperationException("Включите автоопределение БС.");if(!session.Core.Running||session.Core.Starting)throw new InvalidOperationException("Сначала включите подключение.");int generation=session.Core.StartGeneration;int direct=await Task.Run(()=>session.Core.ProbeDirectAccess(BsDetectionSites.Load(session.State.AutoBsSites),!session.State.AutoBsActive));if(closing||closeRequested||!session.Core.Running||session.Core.StartGeneration!=generation||!session.State.AutoDetectBs)return;string result=direct<0?"Проверка сети недоступна":direct>0?"Прямой доступ работает · рекомендуется VPN":"Прямой доступ ограничен · рекомендуются белые списки";status.Text=result;RecordEvent("Автоопределение БС: "+result.ToLowerInvariant()+".");});probe.Name="compactProbeNetwork";StyleCompactButton(probe);panel.Children.Add(probe);enabled.Click+=async(s,e)=>{bool wanted=enabled.IsChecked==true;await Run(()=>CompactSetAutoBs(wanted),()=>enabled.IsChecked=session.State.AutoDetectBs);enabled.IsChecked=session.State.AutoDetectBs;};interval.SelectionChanged+=async(s,e)=>{if(interval.SelectedIndex<0||busy)return;int previous=session.State.AutoBsIntervalSeconds,previousIndex=Math.Max(0,Array.IndexOf(intervals,previous));await CompactPersist(()=>session.State.AutoBsIntervalSeconds=intervals[interval.