  UIElement CompactProxySettings(){
   var panel=new StackPanel{Margin=new Thickness(0,4,0,8)};var port=new TextBox{Name="compactProxyPort",Text=session.State.LocalProxyPort.ToString()};var random=new CheckBox{Name="compactProxyRandom",Content="Случайный порт при подключении",IsChecked=session.State.LocalProxyRandomPort,Margin=new Thickness(0,6,0,4)};var share=new CheckBox{Name="compactProxyShare",Content="Разрешить другим устройствам в локальной сети",IsChecked=session.State.LocalProxyShareLan,Margin=new Thickness(0,4,0,4)};var auth=new CheckBox{Name="compactProxyAuth",Content="Требовать логин и пароль",IsChecked=session.State.LocalProxyAuth,Margin=new Thickness(0,4,0,4)};
   var user=new TextBox{Name="compactProxyUser",Text=session.State.LocalProxyUsername};var password=new PasswordBox{Name="compactProxyPassword",Password=session.State.LocalProxyPassword??"",Background=Brush(CompactLight?"#FFFFFF":"#20262D"),Foreground=Brush(CompactPrimary),BorderBrush=Brush(CompactOutline)};
   panel.Children.Add(Field("Порт",port));panel.Children.Add(random);panel.Children.Add(share);panel.Children.Add(auth);panel.Children.Add(Field("Логин",user));panel.Children.Add(Field("Пароль",password));var copyHttp=Button("Копировать HTTP",()=>CompactCopy(CompactProxyLink("http")));var copySocks=Button("Копировать SOCKS5",()=>CompactCopy(CompactProxyLink("socks5")));StyleCompactButton(copyHttp);StyleCompactButton(copySocks);panel.Children.Add(Columns(copyHttp,copySocks));
   Action sync=()=>{port.Text=session.State.LocalProxyPort.ToString();random.IsChecked=session.State.LocalProxyRandomPort;share.IsChecked=session.State.LocalProxyShareLan;auth.IsChecked=session.State.LocalProxyAuth;user.Text=session.State.LocalProxyUsername;password.Password=session.State.LocalProxyPassword??"";};
   Func<Task> save=()=>{int value;if(!Int32.TryParse(port.Text,out value)||value<1024||value>65535)throw new FormatException("Порт прокси: 1024–65535.");if(share.IsChecked==true&&auth.IsChecked!=true)throw new InvalidOperationException("Для раздачи в локальную сеть включите авторизацию.");if(auth.IsChecked==true&&(String.IsNullOrWhiteSpace(user.Text)||String.IsNullOrWhiteSpace(password.Password)))throw new InvalidOperationException("Укажите логин и пароль прокси.");return session.ChangeConfiguration(()=>{session.State.LocalProxyPort=value;session.State.LocalProxyRandomPort=random.IsChecked==true;session.State.LocalProxyShareLan=share.IsChecked==true;session.State.LocalProxyAuth=auth.IsChecked==true;session.State.LocalProxyUsername=user.Text.Trim();session.State.LocalProxyPassword=password.Password;});};
   Func<Task> persist=async()=>{if(busy){sync();return;}if(port.Text==session.State.LocalProxyPort.ToString()&&random.IsChecked==session.State.LocalProxyRandomPort&&share.IsChecked==session.State.LocalProxyShareLan&&auth.IsChecked==session.State.LocalProxyAuth&&user.Text.Trim()==(session.State.LocalProxyUsername??"")&&password.Password==(session.State.LocalProxyPassword??""))return;await Run(save,sync);sync();};foreach(var check in new[]{random,share,auth})check.Click+=async(s,e)=>await persist();foreach(var field in new Control[]{port,user,password})field.LostKeyboardFocus+=async(s,e)=>await persist();return panel;
  }
  async void CompactSaveProxy(Func<Task> save){await Run(save);}
  string CompactProxyLink(string scheme){int port=session.Core.Running?session.Core.LocalProxyPort:session.State.LocalProxyPort;string credentials=session.State.LocalProxyAuth?Uri.EscapeDataString(session.State.LocalProxyUsername)+":"+Uri.EscapeDataString(session.State.LocalProxyPassword)+"@":"";return scheme+"://"+credentials+"127.0.0.1:"+port;}
  UIElement CompactUpdatesPanel(){
   if(session.Updates.PreferencesError!=null)return UpdatePreferencesRecovery();
   var panel=new DockPanel{Name="compactUpdatesLayout",LastChildFill=true,Margin=new Thickness(0,4,0,4)};var content=new StackPanel();Action render=null;
   string selectedId=null;
   render=()=>{
    content.Children.Clear();var rows=(session.Updates.Items.Count==0?session.Updates.LocalItems(session.State):session.Updates.Items).Where(i=>i.Kind!="catalog"&&i.Kind!="section").OrderBy(i=>i.Id=="app"?0:i.Kind=="optional"||i.Kind=="mcrf-core"?1:2).ToArray();
    var current=rows.FirstOrDefault(i=>i.Id=="app");var state=Text(current==null?"MCRF · состояние не проверено":"MCRF "+VersionLabel(current.Current)+" · "+current.DisplayStatus,11);state.Name="compactUpdateState";content.Children.Add(state);var activity=Text("",11);activity.Name="compactUpdateActivity";activity.TextWrapping=TextWrapping.Wrap;content.Children.Add(activity);var progress=new ProgressBar{Name="compactUpdateProgress",Style=(Style)FindResource("CompactUpdateProgress"),Minimum=0,Maximum=100,Height=4,Margin=new Thickness(0,4,0,8),Foreground=Brush(CompactVisualAccent),Visibility=Visibility.Collapsed};content.Children.Add(progress);
    var startup=new CheckBox{Name="compactCheckOnStart",Content="Проверять при запуске",IsChecked=session.Updates.Preferences.CheckOnStart,Margin=new Thickness(0,6,0,4)};startup.Click+=async(s,e)=>await PersistUpdatePreference(startup,()=>session.Updates.Preferences.CheckOnStart,value=>session.Updates.Preferences.CheckOnStart=value);content.Children.Add(startup);
    var autoComponents=new CheckBox{Name="compactAutoUpdateComponents",Content="Автоматически обновлять движки и компоненты",IsChecked=session.Updates.Preferences.AutoInstallComponents,Margin=new Thickness(0,4,0,8),ToolTip="Основная программа никогда не устанавливается автоматически"};autoComponents.Click+=async(s,e)=>await PersistUpdatePreference(autoComponents,()=>session.Updates.Preferences.AutoInstallComponents,value=>session.Updates.Preferences.AutoInstallComponents=value);content.Children.Add(autoComponents);
    int selection=Array.FindIndex(rows,item=>item.Id==selectedId);var picker=new ListBox{Name="compactUpdateComponent",Background=Brushes.Transparent,Foreground=Brush(CompactPrimary),BorderThickness=new Thickness(0),MinHeight=0,MaxHeight=Double.PositiveInfinity,ItemsSource=rows,SelectedIndex=rows.Length==0?-1:Math.Max(0,selection),Margin=new Thickness(0,0,0,8)};ScrollViewer.SetHorizontalScrollBarVisibility(picker,ScrollBarVisibility.Disabled);picker.HorizontalContentAlignment=HorizontalAlignment.Stretch;var itemStyle=new Style(typeof(ListBoxItem),(Style)FindResource(typeof(ListBoxItem)));itemStyle.Setters.Add(new Setter(Control.ForegroundProperty,Brush(CompactPrimary)));itemStyle.Setters.Add(new Setter(Control.HorizontalContentAlignmentProperty,HorizontalAlignment.Stretch));picker.ItemContainerStyle=itemStyle;var textFactory=new FrameworkElementFactory(typeof(CellPresenter));textFactory.SetValue(CellPresenter.CreateProperty,new Func<object,UIElement>(value=>CompactUpdateTableRow((UpdateItem)value)));picker.ItemTemplate=new DataTemplate{VisualTree=textFactory};var pickerGroup=Field("Компонент · состояние · размер",picker);content.Children.Add(pickerGroup);var detail=Text("",11);detail.Name="compactUpdateDetail";detail.TextWrapping=TextWrapping.Wrap;content.Children.Add(detail);var release=Button("Открыть страницу релиза",()=>{if(picker.SelectedIndex<0||picker.SelectedIndex>=rows.Length)return;Uri address;if(Uri.TryCreate(rows[picker.SelectedIndex].Url,UriKind.Absolute,out address)&&address.Scheme=="https")System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(address.AbsoluteUri){UseShellExecute=true});});release.Name="compactUpdateRelease";StyleCompactButton(release);content.Children.Add(release);
    Button install=null;Action refresh=()=>{var item=picker.SelectedIndex>=0&&picker.SelectedIndex<rows.Length?rows[picker.SelectedIndex]:null;selectedId=item==null?null:item.Id;bool staged=item!=null&&item.Kind=="app"&&!String.IsNullOrEmpty(item.AppliedVersion);bool missing=item!=null&&item.Kind=="optional"&&item.Package!=null&&!session.Core.Engines.Installed(item.Package.Id);install.Content=staged?"Установить и перезапустить":item!=null&&item.Kind=="app"?"Скачать":missing?"Скачать движок":"Обновить выбранное";detail.Text=item==null?"":JournalStyle.Redact(item.Detail??"");detail.Visibility=String.IsNullOrWhiteSpace(detail.Text)?Visibility.Collapsed:Visibility.Visible;Uri releaseUri;release.Visibility=item!=null&&item.Kind=="link"&&Uri.TryCreate(item.Url,UriKind.Absolute,out releaseUri)&&releaseUri.Scheme=="https"?Visibility.Visible:Visibility.Collapsed;install.IsEnabled=item!=null&&(staged||missing||item.Available&&item.Kind!="link");};
    var check=AsyncButton("Проверить",async()=>{await Task.Run(()=>session.Updates.Check(session.State));RecordEvent(session.Updates.Activity);render();});check.Name="compactCheckUpdates";
    install=AsyncButton("Обновить выбранное",async()=>{
     if(picker.SelectedIndex<0||picker.SelectedIndex>=rows.Length)throw new InvalidOperationException("Выберите компонент.");var item=rows[picker.SelectedIndex];EnsureCanTest();
     if(item.Kind=="app"&&!String.IsNullOrEmpty(item.AppliedVersion)){session.Updates.InstallApplication(item);RequestExit();return;}
     if(item.Kind=="optional"&&!session.Updates.Items.Contains(item)){await session.Core.Engines.Install(item.Package.Id);RecordEvent("Движок "+item.Name+" скачан · SHA-256 проверен.");render();return;}
     if(!session.Updates.Items.Contains(item))throw new InvalidOperationException("Сначала проверьте обновления.");await session.Updates.Apply(item,session.State,session.Store);session.Zapret.ReloadUpdates();session.InvalidateStrategies();RecordEvent("Обновления: "+item.Name+" обновлён.");render();
    });install.Name="compactInstallUpdate";picker.SelectionChanged+=(s,e)=>refresh();StyleCompactButton(check);StyleCompactButton(install,true);var actions=Toolbar(check,install);actions.Margin=new Thickness(0);pickerGroup.Children.Remove(picker);content.Children.Remove(detail);content.Children.Remove(release);var footer=new StackPanel{Margin=new Thickness(0,6,0,0)};footer.Children.Add(detail);footer.Children.Add(release);footer.Children.Add(actions);panel.Children.Clear();DockPanel.SetDock(content,Dock.Top);DockPanel.SetDock(footer,Dock.Bottom);panel.Children.Add(content);panel.Children.Add(footer);panel.Children.Add(picker);refresh();WatchCompactUpdates(activity,progress,check,install,picker,startup,autoComponents,refresh);ApplyCompactControlPalette(panel);
